"""Round 2: leg structure mass cut 5.58 -> <= 4.90 kg (both legs) and the linkage allowance split (<= 0.65 kg both legs, R-001 item 1).
Masses: v3 CAD part masses (v3/cad/export/parts.json, volume x density) and parametric solids for changed parts.
Stress: analytic scaling of the v3 FEA (v3/cad/out/fea_v3.md) — sigma_new = sigma_v3 x load ratio x section ratio. This is NOT a new FEA;
parts without a v3 FEA case (foot plate, pocketed lug/fork) are marked 'FEA required' (see grokbuild/structure_fea.md)."""
import json,math,os
HERE=os.path.dirname(os.path.abspath(__file__)); ROOT=os.path.join(HERE,'..','..')
P={p['name']:p for p in json.load(open(os.path.join(ROOT,'v3/cad/export/parts.json')))}
m=lambda n:P['L_'+n]['mass_kg']
BW3=63.8*9.81; BW=65.0*9.81; rho=2810
F_knee_v3=4064.0; S=json.load(open(os.path.join(ROOT,'modules/actuators/results/sizing.json')))['sel']['knee']
F_knee=S['T_out']/(float(S['label'].split('arm ')[1].split(' mm')[0])/1000)
def tube(D,t): return math.pi*((D/2)**2-(D/2-t)**2), math.pi*(D**4-(D-2*t)**4)/(32*D)   # area mm2, Z mm3
SY=503; FEA={'femur':(47,10.62,12.13),'tibia':(81,6.19,7.06),'clevis':(50,10.09,11.52)}   # peak vM MPa, SF yield, Goodman SF (v3 fea_v3.md, 3 BW)
rows=[]
def box(a,b,c): return a*b*c*1e-9*rho

def add(seg,name,v3,new,how,check): rows.append(dict(seg=seg,part=name,v3_kg=v3,new_kg=new,change=how,check=check))
# femur tube 50x2.0 -> 50x1.6
A0,Z0=tube(50,2.0); A1,Z1=tube(50,1.6); r=(BW/BW3)*(Z0/Z1)
add('thigh','femur tube 7075 Ø50',m('femur tube 7075 Ø50x2.0'),m('femur tube 7075 Ø50x2.0')*A1/A0,'wall 2.0 → 1.6 mm',
    f"σ {FEA['femur'][0]*r:.0f} MPa, SF yield {FEA['femur'][1]/r:.2f}, Goodman {FEA['femur'][2]/r:.2f} (v3 FEA × BW ratio × Z ratio {Z0/Z1:.3f})")
add('thigh','femur collars ×2',m('femur root fillet collar')+m('femur knee fillet collar'),(m('femur root fillet collar')+m('femur knee fillet collar'))*A1/A0,'follow tube wall','with tube')
add('thigh','femur upper lug',m('femur upper lug'),m('femur upper lug')*0.80,'pocket 20 % (side pockets, 3 mm webs) [design rule]','FEA required (no v3 case for lug alone; femur_full SF 10.6 includes it)')
rk=(F_knee/F_knee_v3)/0.85
add('thigh','knee clevis',m('knee clevis (thigh)'),m('knee clevis (thigh)')*0.85,'pocket 15 % in the bridge [design rule]',
    f"σ ≤ {FEA['clevis'][0]*rk:.0f} MPa, SF yield ≥ {FEA['clevis'][1]/rk:.2f}, Goodman ≥ {FEA['clevis'][2]/rk:.2f} (whole v3 stress scaled by knee screw force {F_knee:.0f}/{F_knee_v3:.0f} N and 1/0.85 section; conservative) — confirm by FEA")
A0,Z0=tube(45,2.0); A1,Z1=tube(45,1.6); r=(BW/BW3)*(Z0/Z1)
add('shank','tibia tube 7075 Ø45',m('tibia tube 7075 Ø45x2.0'),m('tibia tube 7075 Ø45x2.0')*A1/A0,'wall 2.0 → 1.6 mm',
    f"σ {FEA['tibia'][0]*r:.0f} MPa, SF yield {FEA['tibia'][1]/r:.2f}, Goodman {FEA['tibia'][2]/r:.2f}")
add('shank','tibia collar',m('tibia ankle fillet collar'),m('tibia ankle fillet collar')*A1/A0,'follow tube wall','with tube')
add('shank','ankle fork',m('ankle fork (shank)'),m('ankle fork (shank)')*0.85,'pocket 15 % [design rule]','FEA required (tibia_full SF 6.2 includes fork)')
lev_v3=box(24,130,12)+2*box(24,8,52+10.5)   # v3 crossbar + cheeks (model.py line 158, r=52)
add('shank','knee tongue (pin lug, lever removed)',m('knee tongue + twin lever (shank)')-lev_v3,(m('knee tongue + twin lever (shank)')-lev_v3)*0.85,f'v3 tongue+twin lever {m("knee tongue + twin lever (shank)"):.3f} minus v3 lever solids {lev_v3:.3f}; pocket 15 % [design rule]','FEA required (knee_clevis case covers the thigh side only)')
add('foot','foot plate + instep lever',m('foot plate + instep lever'),m('foot plate + instep lever')*0.75,'7075 plate → ribbed plate, 25 % lighter: 4 mm skin + 3 mm ribs at 40 mm pitch, instep lever kept [design rule]','FEA required (no v3 foot case): 3 BW heel strike and toe-off at CoP extremes')
tot3=sum(x['v3_kg'] for x in rows); totn=sum(x['new_kg'] for x in rows)
# linkage allowance (both legs <= 0.65 kg). Parametric 7075 solids; trunnion spherical bearings and rod ends stay in the actuator unit mass.
def box(a,b,c): return a*b*c*1e-9*rho
lk=[('knee crossbar + 2 cheeks (lever 47.5 mm)', box(20,130,10)+2*box(20,8,47.5+10),'crossbar 20×130×10, cheeks 20×8×57.5 mm, 7075'),
    ('hip_pitch crossbar + 2 cheeks (lever 50 mm)', box(20,130,10)+2*box(20,8,50+10),'same section, cheeks 20×8×60 mm'),
    ('ankle rod-end lugs on instep (2)', 2*box(15,20,25),'2 lugs 15×20×25 mm on the foot instep (the instep lever itself stays in the foot plate)')]
lk_tot=sum(x[1] for x in lk)
L=['# Leg structure and linkage mass (round 2, per leg; ×2 for both legs)\n','Generated by `structure.py`. Masses: v3 CAD part masses + parametric changes. Stress: analytic scaling of v3 FEA at 65 kg (BW %.0f N) — not a new FEA.\n\n'%BW,
   '| segment | part | v3 CAD kg | new kg | change | check |\n|---|---|---|---|---|---|\n']
for x in rows: L.append(f"| {x['seg']} | {x['part']} | {x['v3_kg']:.3f} | {x['new_kg']:.3f} | {x['change']} | {x['check']} |\n")
L.append(f"| **total per leg** | | **{tot3:.3f}** | **{totn:.3f}** | | |\n| **both legs** | | **{2*tot3:.2f}** | **{2*totn:.2f}** | budget R-001: ≤ 4.90 kg | margin {4.90-2*totn:+.2f} kg |\n")
L.append('\nBoundary (DECISIONS L6): structure = thigh lug, femur tube + collars, knee clevis; tibia tube + collar, ankle fork; foot plate. Not structure: knee lever crossbar + cheeks (moved to the linkage line), ankle cross (Ti, 0.120 kg/leg, joint hardware with the ankle actuator), cable drums (harness).\n')
L.append('\n## Linkage allowance (R-001 item 1: ≤ 0.65 kg both legs)\n\n| item | kg per leg | definition |\n|---|---|---|\n')
for n,v,d in lk: L.append(f'| {n} | {v:.3f} | {d} |\n')
L.append(f'| **sum per leg** | **{lk_tot:.3f}** | |\n| **both legs** | **{2*lk_tot:.3f}** | target ≤ 0.65 → remaining {0.65-2*lk_tot:.3f} kg for the two nut-rotor hubs per unit (Actuators) |\n')
L.append('\nFor Actuators: use 0.65 kg (both legs) as the linkage line in place of the 1.30 kg [EST]. It covers the lever crossbars + cheeks and the instep lugs above (parametric-solid estimate, not CAD) plus whatever remains for the nut-rotor hubs. Trunnion spherical bearings, rod ends and screw rods stay in the actuator unit masses, as in v3 CAD. The hip_pitch pelvis-side trunnion bracket is part of the pelvis shell (Torso placeholder) and is not in this line.\n')
os.makedirs(os.path.join(HERE,'results','r2'),exist_ok=True)
open(os.path.join(HERE,'results','r2','structure_mass.md'),'w').write(''.join(L))
json.dump(dict(rows=rows,per_leg_v3=tot3,per_leg_new=totn,both_new=2*totn,linkage=[dict(item=n,kg=v,defn=d) for n,v,d in lk],linkage_both=2*lk_tot,F_knee_N=F_knee),open(os.path.join(HERE,'results','r2','structure_mass.json'),'w'),indent=1)
print(''.join(L))
